<?php declare(strict_types=1);namespace App\Command;use App\Imperium\Runtime\Senate\SubordinatePersonaFindingReconciliationService;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\InputArgument;use Symfony\Component\Console\Input\InputInterface;use Symfony\Component\Console\Output\OutputInterface;#[AsCommand(name:'imperium:senate:reconcile-subordinate-persona-findings')]final class SenateReconcileSubordinatePersonaFindingsCommand extends Command{public function __construct(private readonly SubordinatePersonaFindingReconciliationService$s){parent::__construct();}protected function configure():void{$this->addArgument('reconciliation-opening-id',InputArgument::REQUIRED);}protected function execute(InputInterface$i,OutputInterface$o):int{try{$r=$this->s->reconcile((string)$i->getArgument('reconciliation-opening-id'));}catch(\Throwable$e){$o->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}$o->writeln('<info>PERSONA_FINDINGS_RECONCILED_PENDING_DISPOSITION_AUTHORITY_OPENING</info> '.$r['reconciliation_id']);return self::SUCCESS;}}
